import { useQuery } from '@tanstack/react-query';
import type { DashboardPeriod, SchemaField } from '../types';
import type { EndpointMeta } from '../api/dashboardProxy';
import { fetchWidgetDataProxy } from '../api/dashboardProxy';
import { useDashboardContext } from '../DashboardContext';

interface UseWidgetFetchResult<T> {
  data: T | null;
  schema: { fields: SchemaField[] } | null;
  meta: EndpointMeta | null;
  loading: boolean;
  error: string | null;
}

/** Accede a un valor anidado via dot-notation (ej: "name.common" → obj.name.common) */
function getNestedValue(obj: Record<string, unknown>, path: string): unknown {
  return path.split('.').reduce<unknown>((acc, key) =>
    acc != null && typeof acc === 'object' ? (acc as Record<string, unknown>)[key] : undefined, obj);
}

function applyFieldMapping(data: unknown, mapping: Record<string, string>): unknown {
  const entries = Object.entries(mapping);
  if (entries.length === 0) return data;

  // Advertir en desarrollo si el campo a renombrar no existe en la respuesta
  if (process.env.NODE_ENV === 'development') {
    const sample = Array.isArray(data) ? data[0] : data;
    if (sample && typeof sample === 'object') {
      for (const [, apiField] of entries) {
        const topLevelField = apiField.split('.')[0];
        if (!(topLevelField in (sample as object))) {
          // eslint-disable-next-line no-console
          console.warn(
            `[KPI Dashboard] field_mapping.rename: el campo "${apiField}" no existe en la respuesta del endpoint. ` +
            `Verificar que el nombre coincida exactamente con el campo devuelto por la API.`
          );
        }
      }
    }
  }

  const mapObject = (obj: Record<string, unknown>): Record<string, unknown> => {
    const result: Record<string, unknown> = { ...obj };
    for (const [widgetField, apiField] of entries) {
      const val = apiField.includes('.') ? getNestedValue(obj, apiField) : obj[apiField];
      if (val !== undefined) {
        result[widgetField] = val;
      }
    }
    return result;
  };

  if (Array.isArray(data)) {
    return data.map(item =>
      typeof item === 'object' && item !== null ? mapObject(item as Record<string, unknown>) : item
    );
  }

  if (typeof data === 'object' && data !== null) {
    return mapObject(data as Record<string, unknown>);
  }

  return data;
}

interface CachedQueryData<T> {
  data: T;
  schema: { fields: SchemaField[] } | null;
  meta: EndpointMeta | null;
}

/**
 * Hook centralizado para fetching de datos de widgets.
 * Retorna data (post field_mapping) + schema del endpoint (si disponible).
 */
export function useWidgetFetch<T>(
  widgetId: string,
  period: DashboardPeriod,
  refreshPolicy?: number,
  fieldMapping?: Record<string, string>
): UseWidgetFetchResult<T> {
  const { fetcher } = useDashboardContext();

  const { data: result, isLoading, error } = useQuery<CachedQueryData<T>>({
    queryKey: ['widget-data', widgetId, period],
    queryFn: async () => {
      const { data: raw, schema, endpointMeta } = await fetchWidgetDataProxy({ widgetId, period }, fetcher);
      let mapped = raw;
      if (fieldMapping && Object.keys(fieldMapping).length > 0) {
        mapped = applyFieldMapping(raw, fieldMapping);
      }
      return { data: mapped as T, schema, meta: endpointMeta };
    },
    // Mínimo 10 segundos para evitar polling agresivo por configuración incorrecta
    refetchInterval: refreshPolicy && refreshPolicy > 0
      ? Math.max(refreshPolicy, 10) * 1000
      : false,
  });

  return {
    data: result?.data ?? null,
    schema: result?.schema ?? null,
    meta: result?.meta ?? null,
    loading: isLoading,
    error: error ? (error as Error).message : null,
  };
}
